def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    last_my, last_op = my[-1], op[-1]

    opp_d = 0
    my_d = 0
    for i in range(n):
        if op[i] == 'D':
            opp_d += 1
        if my[i] == 'D':
            my_d += 1
    rate = (n - opp_d) / n

    w = min(5, n)
    d5 = sum(1 for x in op[n - w:n] if x == 'D')
    w = min(10, n)
    d10 = sum(1 for x in op[n - w:n] if x == 'D')

    def_streak = 0
    for x in reversed(op):
        if x == 'D':
            def_streak += 1
        else:
            break

    dd_streak = 0
    for a, b in reversed(history):
        if a == 'D' and b == 'D':
            dd_streak += 1
        else:
            break

    prev_c = 0
    prev_d = 0
    pc = 0
    pd = 0
    cur_tot = 0
    cur_c = 0
    for i in range(n - 1):
        if my[i] == 'C':
            prev_c += 1
            if op[i + 1] == 'C':
                pc += 1
        else:
            prev_d += 1
            if op[i + 1] == 'C':
                pd += 1

        if my[i] == last_my:
            cur_tot += 1
            if op[i + 1] == 'C':
                cur_c += 1

    if rate >= 0.85:
        base_c = 0.8
    elif rate >= 0.6:
        base_c = 0.65
    elif rate >= 0.35:
        base_c = 0.45
    else:
        base_c = 0.3

    if prev_c == 0:
        pC_C = base_c
    else:
        pC_C = (pc + base_c) / (prev_c + 1)

    if prev_d == 0:
        pC_D = 0.3
    else:
        if rate >= 0.8:
            base_d = 0.6
        elif rate >= 0.6:
            base_d = 0.55
        elif rate >= 0.5:
            base_d = 0.5
        elif rate >= 0.35:
            base_d = 0.45
        else:
            base_d = 0.4
        pC_D = (pd + base_d) / (prev_d + 1)

    if last_my == 'C':
        prior_now = pC_C
    else:
        prior_now = pC_D

    if cur_tot == 0:
        p_now = prior_now
    elif cur_tot >= 4:
        p_now = cur_c / cur_tot
    else:
        p_now = (cur_c + prior_now) / (cur_tot + 1)

    if last_my == 'D' and last_op == 'C' and prev_d == 0 and n < 95:
        return 'C'

    forgiving = (
        prev_d >= 1
        and pC_D >= 0.7
        and rate >= 0.5
        and d5 <= 3
        and (
            last_op == 'C'
            or (pC_D >= 0.75 and def_streak <= 2 and dd_streak <= 1)
        )
    )

    if forgiving:
        return 'D'

    if not forgiving:
        if n >= 4 and opp_d == n:
            return 'D'
        if d10 >= 8:
            return 'D'
        if def_streak >= 5 and rate <= 0.5 and pC_C < 0.55:
            return 'D'
        if d5 >= 4 and def_streak >= 3 and rate <= 0.65:
            return 'D'

    remaining = 100 - n

    if remaining <= 3:
        if remaining == 1:
            return 'D'
        if remaining == 2:
            vC = 3.0 * p_now + 1.0 + 4.0 * pC_C
            vD = 1.0 + 4.0 * p_now + 1.0 + 4.0 * pC_D
            if vD > vC:
                return 'D'
            return 'C'

        x = pC_C
        val2C_c = 3.0 * x + 1.0 + 4.0 * pC_C
        val2C_d = 2.0 + 4.0 * x + 4.0 * pC_D
        val2C = val2C_c if val2C_c > val2C_d else val2C_d

        x = pC_D
        val2D_c = 3.0 * x + 1.0 + 4.0 * pC_C
        val2D_d = 2.0 + 4.0 * x + 4.0 * pC_D
        val2D = val2D_c if val2D_c > val2D_d else val2D_d

        vC = 3.0 * p_now + val2C
        vD = 1.0 + 4.0 * p_now + val2D
        if vD > vC:
            return 'D'
        return 'C'

    if last_op == 'D':
        if (
            last_my == 'C'
            and n >= 2
            and my[-2] == 'D'
            and def_streak == 1
            and pC_C >= 0.6
            and rate >= 0.55
        ):
            return 'C'

        if my_d >= opp_d and pC_C >= 0.6 and def_streak <= 3 and rate >= 0.45:
            return 'C'

        if (
            dd_streak >= 2
            and def_streak >= 4
            and pC_C >= 0.6
            and def_streak <= 8
            and rate >= 0.45
        ):
            return 'C'

        if def_streak <= 3 and opp_d <= 4 and rate >= 0.6:
            return 'D'

        if def_streak >= 4 and rate >= 0.55 and pC_C >= 0.6:
            return 'C'

        if opp_d == 1 and rate >= 0.65:
            return 'D'

        if rate <= 0.35 or d5 >= 3 or def_streak >= 6:
            return 'D'

        return 'D'

    if rate < 0.35 and d5 >= 3:
        return 'D'
    if d10 >= 6 and def_streak >= 2:
        return 'D'
    if pC_D <= 0.35 and d5 >= 3:
        return 'D'

    if rate >= 0.85 and d10 <= 1 and 25 <= n < 90:
        if rng.random() < 0.04:
            return 'D'

    if opp_d == 0 and rate >= 0.95 and n >= 70 and last_my == 'C':
        return 'D'

    if opp_d <= 2 and rate >= 0.85 and d5 == 0 and n >= 65 and last_my == 'C':
        if rng.random() < 0.25:
            return 'D'

    if my_d > opp_d + 8:
        return 'C'

    return 'C'
